-- ============================================================================
-- V4: 协同办公 - 会议纪要（W3-a）
-- 1) coll_meeting 表
-- 2) 字典 icp_meeting_type（0 周例会 / 1 专题会 / 2 评审会 / 3 培训会）
-- 3) 菜单「会议纪要」（协同办公 → 会议纪要）与 4 个按钮权限
-- 4) 20 条业务化种子会议（12 条已召开且含纪要正文、5 条待召开、3 条已取消）
-- ============================================================================

CREATE TABLE coll_meeting (
    id             BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
    meeting_no     VARCHAR(32)  NOT NULL COMMENT '会议编号 HY-yyyy-###',
    title          VARCHAR(200) NOT NULL COMMENT '会议标题',
    meeting_type   VARCHAR(32)  NOT NULL DEFAULT '0' COMMENT '会议类型 0周例会 1专题会 2评审会 3培训会',
    start_time     DATETIME     NOT NULL COMMENT '开始时间',
    end_time       DATETIME     NULL COMMENT '结束时间',
    location       VARCHAR(200) NULL COMMENT '会议地点',
    organizer_id   BIGINT       NULL COMMENT '组织者ID',
    organizer_name VARCHAR(64)  NULL COMMENT '组织者姓名',
    dept_id        BIGINT       NULL COMMENT '所属部门ID',
    dept_name      VARCHAR(64)  NULL COMMENT '所属部门名称',
    attendee_names VARCHAR(500) NULL COMMENT '参会人姓名，逗号分隔',
    attendee_count INT          NOT NULL DEFAULT 0 COMMENT '参会人数',
    minutes        TEXT         NULL COMMENT '会议纪要正文',
    status         TINYINT      NOT NULL DEFAULT 0 COMMENT '0待召开 1已召开 2已取消',
    remark         VARCHAR(500) NULL COMMENT '备注',
    tenant_id      BIGINT       NOT NULL DEFAULT 0 COMMENT '租户ID(预留)',
    create_by      BIGINT       NULL COMMENT '创建人',
    create_time    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    update_by      BIGINT       NULL COMMENT '更新人',
    update_time    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    deleted        TINYINT      NOT NULL DEFAULT 0 COMMENT '逻辑删除 0否 1是',
    PRIMARY KEY (id),
    UNIQUE KEY uk_meeting_no (meeting_no),
    KEY idx_meeting_start_time (start_time),
    KEY idx_meeting_dept (dept_id),
    KEY idx_meeting_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='会议纪要';





