(3501, 'HY-2026-001', '2026年第三季度内控评价工作部署会', '1', '2026-09-03 09:30:00', '2026-09-03 11:00:00', '总部 3 层会议室', 3, '李静', 2, '内控合规部', '赵敏、张伟、王芳、孙丽、吴磊、郑爽', 6, '会议明确第三季度内部控制评价范围覆盖制度、风险、缺陷与整改四个维度，由内控合规部牵头制定评价计划，各部门于9月15日前完成自查底稿。议定事项：一、10月10日前完成现场评价；二、评价发现问题统一纳入缺陷台账；三、整改时限原则上不超过30日。', 1, '季度评价部署', 0, 1, '2026-09-01 09:00:00', NULL, '2026-09-01 09:00:00', 0),
(3502, 'HY-2026-002', '2026年9月内控工作例会', '0', '2026-09-18 14:00:00', '2026-09-18 15:30:00', '总部 3 层会议室', 3, '李静', 2, '内控合规部', '赵敏、孙丽、吴磊、曹阳、谢慧、郑爽', 6, '各部门汇报本月内控执行情况，制度发布与风险更新按计划推进。议定事项：一、下月重点检查采购与资金审批流程；二、风险清单新增一项供应商集中度风险；三、各部门按时提交控制执行记录，由内控合规部汇总归档。', 1, '月度例会', 0, 1, '2026-09-15 09:00:00', NULL, '2026-09-15 09:00:00', 0),
(3503, 'HY-2026-003', '采购制度修订专题会', '1', '2026-09-24 09:00:00', '2026-09-24 11:00:00', '总部 3 层会议室', 7, '刘强', 6, '采购部', '王芳、张伟、冯超、邓琳、罗刚、苏娜', 6, '会议逐条审议采购管理制度修订稿，重点讨论供应商准入、比价与验收环节。议定事项：一、新增供应商年度复评要求；二、单笔50万元以上采购须经集体决策；三、修订稿由采购部完善后提交审批发布。', 1, '制度修订', 0, 1, '2026-09-20 09:00:00', NULL, '2026-09-20 09:00:00', 0),
(3504, 'HY-2026-004', '财务报销流程优化评审会', '2', '2026-10-09 10:00:00', '2026-10-09 11:30:00', '总部 3 层会议室', 5, '张伟', 4, '财务部', '李静、孙丽、吴磊、许凯、苏娜、郑爽', 6, '评审财务报销线上流程优化方案，明确发票查验、审批层级与归档要求。议定事项：一、报销单增加电子发票验真环节；二、差旅与业务招待费实行分级审批；三、优化方案自11月起试运行。', 1, '流程优化评审', 0, 1, '2026-10-05 09:00:00', NULL, '2026-10-05 09:00:00', 0),
(3505, 'HY-2026-005', '合同管理风险专项研讨会', '1', '2026-10-15 14:00:00', '2026-10-15 16:00:00', '总部 3 层会议室', 3, '李静', 2, '内控合规部', '赵敏、张伟、王芳、刘强、高敏、吕鹏', 6, '围绕合同订立、履行与归档环节识别风险，讨论合同范本库与法律审核机制。议定事项：一、重大合同必须经法务审核；二、建立合同履行台账；三、每季度开展合同抽查并通报结果。', 1, '合同风险研讨', 0, 1, '2026-10-10 09:00:00', NULL, '2026-10-10 09:00:00', 0),
(3506, 'HY-2026-006', '信息安全等级保护工作例会', '0', '2026-10-16 09:30:00', '2026-10-16 11:00:00', '总部 3 层会议室', 9, '杨洋', 8, '信息技术部', '曹阳、韩雪、沈鹏、曾辉、吕鹏、郑爽', 6, '信息技术部汇报等级保护测评整改进展，讨论账号权限与数据备份策略。议定事项：一、10月底前完成弱口令整改；二、核心系统实行双人复核；三、每季度组织一次数据恢复演练。', 1, '等保整改', 0, 1, '2026-10-12 09:00:00', NULL, '2026-10-12 09:00:00', 0),
(3507, 'HY-2026-007', '供应商管理制度评审会', '2', '2026-10-21 09:00:00', '2026-10-21 11:00:00', '总部 3 层会议室', 7, '刘强', 6, '采购部', '王芳、冯超、罗刚、邓琳', 4, NULL, 2, '议程冲突取消', 0, 1, '2026-10-16 09:00:00', NULL, '2026-10-18 09:00:00', 0),
(3508, 'HY-2026-008', '预算执行情况分析会', '0', '2026-10-23 14:00:00', '2026-10-23 16:00:00', '总部 3 层会议室', 5, '张伟', 4, '财务部', '李静、孙丽、许凯、苏娜、蒋鑫、郑爽', 6, '财务部通报前三季度预算执行率，分析偏差原因并部署四季度控制措施。议定事项：一、严控非刚性支出；二、超预算项目须专项审批；三、12月上旬完成年度预算调整方案。', 1, '预算执行分析', 0, 1, '2026-10-19 09:00:00', NULL, '2026-10-19 09:00:00', 0),
(3509, 'HY-2026-009', '固定资产盘点工作部署会', '1', '2026-10-28 09:30:00', '2026-10-28 11:00:00', '总部 3 层会议室', 5, '张伟', 4, '财务部', '王芳、冯超、孙丽、彭丹、苏娜、郑爽', 6, '会议部署年度固定资产盘点工作，明确盘点范围、时间安排与责任分工。议定事项：一、11月完成全公司资产盘点；二、账实不符的资产逐项说明原因；三、盘点结果纳入部门内控考核。', 1, '资产盘点部署', 0, 1, '2026-10-24 09:00:00', NULL, '2026-10-24 09:00:00', 0),
(3510, 'HY-2026-010', '印章使用管理规范培训会', '3', '2026-10-29 14:00:00', '2026-10-29 16:00:00', '总部 3 层会议室', 6, '王芳', 5, '人力行政部', '孙丽、蒋婷、彭丹、曹阳、谢慧、张伟', 6, '培训讲解印章保管、审批与用印登记要求，结合典型案例提示用印风险。议定事项：一、用印须线上申请并留存审批记录；二、印章保管人离岗须办理交接；三、每半年开展一次用印检查。', 1, '印章规范培训', 0, 1, '2026-10-25 09:00:00', NULL, '2026-10-25 09:00:00', 0),
(3511, 'HY-2026-011', '档案归档与借阅流程培训会', '3', '2026-11-03 09:30:00', '2026-11-03 11:30:00', '总部 3 层会议室', 6, '王芳', 5, '人力行政部', '孙丽、蒋婷、彭丹、邓琳、苏娜', 5, NULL, 2, '培训计划调整取消', 0, 1, '2026-10-28 09:00:00', NULL, '2026-11-01 09:00:00', 0),
(3512, 'HY-2026-012', '内部审计发现问题整改推进会', '1', '2026-11-01 09:30:00', '2026-11-01 11:00:00', '总部 3 层会议室', 4, '赵敏', 3, '审计部', '李静、郑爽、谢慧、吴磊、张伟、高敏', 6, '审计部通报本年度审计发现问题整改进度，逐项明确责任人与完成时限。议定事项：一、未整改问题11月底前完成销号；二、整改证据须完整上传系统；三、对整改不力的部门进行约谈。', 1, '审计整改推进', 0, 1, '2026-10-27 09:00:00', NULL, '2026-10-27 09:00:00', 0),
